import re

def parse_duration(text: str) -> int:
    if not text or not text.strip():
        raise ValueError("Empty input")

    pairs = re.findall(r'\d+[dhms]', text)
    if not pairs:
        raise ValueError("No valid duration parts found")

    cleaned = ''.join(text.split())
    if ''.join(pairs) != cleaned:
        raise ValueError("Malformed input")

    units = [p[-1] for p in pairs]
    order_map = {'d': 0, 'h': 1, 'm': 2, 's': 3}
    last_idx = -1
    seen = set()
    for u in units:
        idx = order_map[u]
        if idx <= last_idx:
            raise ValueError("Out of order or repeated units")
        if u in seen:
            raise ValueError("Repeated unit")
        seen.add(u)
        last_idx = idx

    multipliers = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    total = sum(int(p[:-1]) * multipliers[p[-1]] for p in pairs)
    return total
