        bv = b_nums[i] if i < len(b_nums) else 0
        if av < bv:
            return -1
        if av > bv:
            return 1

    # Compare pre-release presence
    if a_pre is None and b_pre is None:
        return 0
    if a_pre is not None and b_pre is None:
        return -1
    if a_pre is None and b_pre is not None:
        return 1

