import re

def parse_duration(text: str) -> int:
    if not re.fullmatch(r'\s*(?:\d+\s*[dhms]\s*)+', text):
        raise ValueError("Invalid duration format")

    matches = re.findall(r'\d+\s*[dhms]', text)
    if not matches:
        raise ValueError("No valid duration parts found")

    units_order = {'d': 0, 'h': 1, 'm': 2, 's': 3}
    last_unit_idx = -1
    seen_units = set()
    total_seconds = 0

    for match in matches:
        num_str = match[:-1].strip()
        unit = match[-1]

        if unit in seen_units:
            raise ValueError("Repeated unit")
        seen_units.add(unit)

        current_unit_idx = units_order[unit]
        if current_unit_idx <= last_unit_idx:
            raise ValueError("Out-of-order units")
        last_unit_idx = current_unit_idx

        num = int(num_str)
        if unit == 'd':
            total_seconds += num * 86400
        elif unit == 'h':
            total_seconds += num * 3600
        elif unit == 'm':
            total_seconds += num * 60
        elif unit == 's':
            total_seconds += num

    return total_seconds
