def compare_semver(a: str, b: str) -> int:
    def parse(v):
        # Remove build metadata (everything after '+')
        if '+' in v:
            v = v[:v.index('+')]

        # Separate pre-release identifier (everything after '-')
        # split('-', 1) handles hyphens within pre-release identifiers correctly
        if '-' in v:
            core, pre = v.split('-', 1)
        else:
            core, pre = v, None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        pre_ids = None
        if pre is not None:
            pre_ids = pre.split('.')

        return (major, minor, patch, pre_ids)

    va = parse(a)
    vb = parse(b)

    # Compare MAJOR.MINOR.PATCH numerically
    for i in range(3):
        if va[i] < vb[i]:
            return -1
        if va[i] > vb[i]:
            return 1

    # Compare Pre-release
    pa = va[3]
    pb = vb[3]

    # Rule: A version with pre-release has lower precedence than same version without
    if pa is None and pb is None:
        return 0
    if pa is None:
        return 1  # a > b
    if pb is None:
        return -1 # a < b

    # Both have pre-release, compare identifiers dot by dot
    for x, y in zip(pa, pb):
        x_is_num = x.isdigit()
        y_is_num = y.isdigit()

        if x_is_num and y_is_num:
            # Compare as integers
            xi, yi = int(x), int(y)
            if xi < yi:
                return -1
            if xi > yi:
                return 1
        elif x_is_num:
            # Numeric identifiers have lower precedence than alphanumeric
            return -1
        elif y_is_num:
            # Alphanumeric identifiers have higher precedence than numeric
            return 1
        else:
            # Compare alphanumeric identifiers in ASCII sort order
            if x < y:
                return -1
            if x > y:
                return 1

    # If all preceding identifiers are equal, shorter set has lower precedence
    if len(pa) < len(pb):
        return -1
    if len(pa) > len(pb):
        return 1

    return 0
